// Get GSC response data
const gscData = $input.first().json;
const rows = gscData.rows || [];

// Get config from Calculate Date Range node
const dateConfig = $('Calculate Date Range').first().json;
const minClicks = dateConfig.minClicks || 10;
const minImpressions = dateConfig.minImpressions || 20;
const days = dateConfig.days || 7;
const startDate = dateConfig.startDate;
const endDate = dateConfig.endDate;

// Calculate TOTAL stats from ALL pages
const totalClicks = rows.reduce((sum, row) => sum + row.clicks, 0);
const totalImpressions = rows.reduce((sum, row) => sum + row.impressions, 0);
const avgCTR = totalImpressions > 0 ? ((totalClicks / totalImpressions) * 100).toFixed(2) : '0.00';

// Filter pages that meet criteria
const qualifying = rows.filter(row => 
  row.clicks >= minClicks && row.impressions >= minImpressions
);

// Sort qualifying pages by clicks descending
qualifying.sort((a, b) => b.clicks - a.clicks);

return [{
  json: {
    qualifyingPages: qualifying,
    totalQualifying: qualifying.length,
    totalPages: rows.length,
    criteria: {
      minClicks,
      minImpressions
    },
    dateRange: {
      startDate,
      endDate,
      days
    },
    // TOTAL stats from ALL pages
    totalClicks,
    totalImpressions,
    avgCTR
  }
}];

// ============================================================
// Generates the Search Console performance report HTML.
// Output feeds TWO downstream paths — keep the JSON shape
// (htmlReport, hasData, totalQualifying, dateRange, periodText)
// exactly as before so both keep working:
//   1) Convert HTML to Image -> Send to Telegram
//   2) Send Report Email (htmlReport used as the email body)
//
// v4 — rebuilt on the exact pattern from your "Special Package
// Upload Report" template, which you confirmed renders correctly
// on mobile Gmail. Content/data logic is unchanged; only the
// markup technique changed, for these concrete reasons:
//
//  1) THE MEDIA QUERY SELECTOR WAS THE ACTUAL BUG LAST TIME.
//     v3 used `.kpi-row td{ display:block!important; ... }` — a
//     COMPOUND selector (a class, then a descendant tag). Your
//     working template only ever uses a single class selector
//     applied directly to the element being changed (e.g.
//     `.summary-cell{...}` on a <td class="summary-cell">, never
//     `.summary-table td{...}`). Gmail's mobile renderer is picky
//     about this — compound/descendant selectors in <style> don't
//     reliably apply, so the KPI cards never stacked and instead
//     overflowed sideways, which is exactly what your screenshots
//     showed (cards cut off, void space around them). Every
//     responsive rule below now targets a single class directly
//     on its element, matching your working template exactly.
//
//  2) DROPPED THE GOOGLE FONTS <link> AND THE color-scheme META
//     TAGS. Your working template doesn't use either, and adding
//     them last time didn't fix (and may have worsened) the dark
//     background issue — likely because these interact with
//     Gmail's own dark-mode + clipping heuristics in ways that
//     are hard to predict across app versions. The fix that
//     actually works, per your reference template, is simpler:
//     plain system fonts (Arial/Helvetica) and an explicit
//     background/bgcolor on every colored block, which is what's
//     below — nothing left for Gmail to "guess" and re-theme.
//
//  3) THE WIDE 5-COLUMN TABLE now uses the same technique as your
//     working template's package table: a real table with a
//     `min-width`, wrapped in a horizontally-scrollable container
//     (`overflow-x:auto`), instead of my earlier approach of
//     generating a second, separate "card" markup block toggled
//     by CSS. Since your reference template proves the
//     scroll-table approach renders correctly on your phone, this
//     keeps the fix consistent with what's already known to work,
//     and avoids maintaining two parallel versions of the same
//     data.
//
//  4) No hardcoded pixel `width=` HTML attribute anywhere — only
//     `width="100%"` plus `max-width` in CSS (a ceiling, not a
//     forced size), so it's never hardcoded to one screen size.
// ============================================================
const data = $input.first().json;
const pages = data.qualifyingPages || [];
const total = data.totalQualifying || 0;
const criteria = data.criteria || {};
const dateRange = data.dateRange || {};

const totalClicks = data.totalClicks || 0;
const totalImpressions = data.totalImpressions || 0;
const avgCTR = data.avgCTR || '0.00';

const periodText = dateRange.days === 1 ? "Last 24 Hours" : dateRange.days === 7 ? "Last 7 Days" : dateRange.days === 28 ? "Last 28 Days" : dateRange.days === 30 ? "Last Month" : dateRange.days === 90 ? "Last 3 Months" : "Last " + dateRange.days + " Days";
const dateRangeText = dateRange.startDate + " to " + dateRange.endDate;

function esc(str) {
  return String(str == null ? '' : str)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// ---------- shared shell (header + footer + responsive CSS wrap everything, incl. empty state) ----------
function shell(bodyHtml) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Search Console Performance Report</title>
<style>
  @media only screen and (max-width: 700px) {
    .email-container { width:100% !important; max-width:100% !important; }
    .mobile-padding { padding-left:14px !important; padding-right:14px !important; }
    .summary-table { width:100% !important; }
    .summary-cell {
      display:block !important;
      width:100% !important;
      box-sizing:border-box !important;
      border-right:none !important;
      border-bottom:1px solid #e2e8f0 !important;
    }
    .data-table { min-width:650px !important; }
    .table-wrapper { overflow-x:auto !important; -webkit-overflow-scrolling:touch !important; }
    .header-title { font-size:22px !important; line-height:1.3 !important; }
    .header-date { font-size:13px !important; }
  }
</style>
</head>
<body style="margin:0;padding:0;background:#f1f5f9;font-family:Arial,Helvetica,sans-serif;color:#0f172a;">

  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f1f5f9;">
    <tr>
      <td align="center" style="padding:25px 10px;">

        <table class="email-container" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:1000px;background:#ffffff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;">

          <!-- Header -->
          <tr>
            <td style="background:linear-gradient(120deg,#4338ca 0%,#6366f1 55%,#8b5cf6 100%);padding:28px 30px;">
              <div style="color:#e0e7ff;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:1.5px;margin-bottom:8px;">Search Console</div>
              <div class="header-title" style="color:#ffffff;font-size:27px;font-weight:800;line-height:1.3;margin-bottom:8px;">Performance Report</div>
              <div class="header-date" style="color:#e0e7ff;font-size:14px;line-height:1.5;">
                <span style="display:inline-block;background:rgba(255,255,255,0.18);border-radius:5px;padding:4px 10px;font-weight:700;margin-right:6px;">vodbangla.com &bull; Discover</span><br>
                <span style="display:inline-block;margin-top:6px;">${esc(periodText)} &bull; ${esc(dateRangeText)}</span>
              </div>
            </td>
          </tr>

          ${bodyHtml}

          <!-- Footer -->
          <tr>
            <td style="padding:18px 28px;background:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;">
              <div style="color:#64748b;font-size:11px;line-height:1.6;">
                Report generated: <strong style="color:#1e293b;">${esc(new Date().toLocaleDateString("en-US", { weekday: "long", year: "numeric", month: "long", day: "numeric" }))}</strong><br>
                Powered by Google Search Console API &bull; Discover Search Type
              </div>
            </td>
          </tr>

        </table>

      </td>
    </tr>
  </table>

</body>
</html>`;
}

// ---------- empty state ----------
if (pages.length === 0) {
  const emptyBody = `
          <tr>
            <td class="mobile-padding" style="padding:28px;">
              <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;">
                <tr>
                  <td style="padding:36px;text-align:center;">
                    <div style="font-size:32px;margin-bottom:10px;">\ud83d\udce7</div>
                    <div style="font-size:17px;font-weight:800;color:#0f172a;margin-bottom:6px;">No pages met the criteria this period</div>
                    <div style="font-size:13.5px;color:#64748b;">Total clicks: <strong style="color:#0f172a;">${totalClicks.toLocaleString()}</strong> &nbsp;&bull;&nbsp; Total impressions: <strong style="color:#0f172a;">${totalImpressions.toLocaleString()}</strong></div>
                  </td>
                </tr>
              </table>
            </td>
          </tr>`;

  return [{
    json: {
      htmlReport: shell(emptyBody),
      hasData: false,
      dateRange: dateRangeText,
      periodText: periodText
    }
  }];
}

// ---------- KPI / summary cards (single-class stacking, matches your working template) ----------
function summaryCell(bg, accent, value, label, last) {
  return `
                  <td class="summary-cell" width="33.33%" style="padding:17px;${last ? '' : 'border-right:1px solid #e2e8f0;'}background:${bg};">
                    <div style="color:${accent};font-size:25px;font-weight:800;">${value}</div>
                    <div style="color:#64748b;font-size:11px;font-weight:700;text-transform:uppercase;margin-top:3px;">${esc(label)}</div>
                  </td>`;
}

const summaryBlock = `
          <tr>
            <td class="mobile-padding" style="padding:24px 28px 10px 28px;">
              <div style="color:#0f172a;font-size:16px;font-weight:800;margin-bottom:12px;">Key Metrics</div>
              <table class="summary-table" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid #e2e8f0;border-radius:8px;overflow:hidden;">
                <tr>
${summaryCell('#f0fdf4', '#15803d', totalClicks.toLocaleString(), 'Total Clicks')}
${summaryCell('#eff6ff', '#1d4ed8', totalImpressions.toLocaleString(), 'Total Impressions')}
${summaryCell('#f5f3ff', '#7c3aed', avgCTR + '%', 'Average CTR', true)}
                </tr>
              </table>
            </td>
          </tr>

          <tr>
            <td class="mobile-padding" style="padding:10px 28px 10px 28px;">
              <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f5f5fc;border-radius:8px;border-left:4px solid #6366f1;">
                <tr>
                  <td style="padding:18px 20px;">
                    <div style="color:#0f172a;font-size:14px;font-weight:800;margin-bottom:10px;">\ud83d\udccb Report Summary</div>
                    <div style="font-size:13.5px;color:#64748b;line-height:1.9;">
                      <strong style="color:#0f172a;">Qualifying Pages:</strong> ${total} pages &nbsp;&bull;&nbsp;
                      <strong style="color:#0f172a;">Total Pages:</strong> ${(data.totalPages || 0).toLocaleString()}<br>
                      <strong style="color:#0f172a;">Criteria:</strong> Clicks \u2265 ${(criteria.minClicks || 0).toLocaleString()} AND Impressions \u2265 ${(criteria.minImpressions || 0).toLocaleString()}
                    </div>
                  </td>
                </tr>
              </table>
            </td>
          </tr>`;

// ---------- top pages table (scrollable on mobile, same technique as your working template) ----------
const tableRows = pages.slice(0, 10).map((page, i) => {
  const url = page.keys[0];
  const shortUrl = url.length > 80 ? url.substring(0, 77) + "..." : url;
  const medal = i === 0 ? "\ud83e\udd47" : i === 1 ? "\ud83e\udd48" : i === 2 ? "\ud83e\udd49" : "";
  const ctr = (page.ctr !== undefined && page.ctr !== null) ? (page.ctr * 100).toFixed(2) : '0.00';
  const rowBg = i % 2 === 0 ? '#ffffff' : '#f8fafc';

  return (
    '<tr style="background:' + rowBg + ';">' +
    '<td style="padding:14px 12px;border-bottom:1px solid #e2e8f0;color:#6366f1;font-size:14px;font-weight:800;text-align:center;vertical-align:top;width:40px;">' + medal + (medal ? ' ' : '') + (i + 1) + '</td>' +
    '<td style="padding:14px;border-bottom:1px solid #e2e8f0;vertical-align:top;min-width:220px;"><a href="' + esc(url) + '" target="_blank" style="color:#2563eb;text-decoration:none;font-size:13px;font-weight:600;word-break:break-word;line-height:1.5;">' + esc(shortUrl) + '</a></td>' +
    '<td style="padding:14px 12px;border-bottom:1px solid #e2e8f0;text-align:center;vertical-align:top;white-space:nowrap;"><span style="color:#15803d;font-size:14px;font-weight:800;">' + page.clicks.toLocaleString() + '</span></td>' +
    '<td style="padding:14px 12px;border-bottom:1px solid #e2e8f0;text-align:center;vertical-align:top;color:#64748b;font-size:13px;font-weight:600;white-space:nowrap;">' + page.impressions.toLocaleString() + '</td>' +
    '<td style="padding:14px 12px;border-bottom:1px solid #e2e8f0;text-align:center;vertical-align:top;white-space:nowrap;"><span style="color:#7c3aed;font-size:13px;font-weight:800;">' + ctr + '%</span></td>' +
    '</tr>'
  );
}).join("");

const tableBlock = `
          <tr>
            <td class="mobile-padding" style="padding:18px 28px 28px 28px;">
              <div style="color:#0f172a;font-size:16px;font-weight:800;margin-bottom:12px;">\ud83d\udd1d Top Performing Pages</div>

              <div class="table-wrapper" style="width:100%;overflow-x:auto;border:1px solid #cbd5e1;border-radius:8px;">
                <table class="data-table" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse;background:#ffffff;">
                  <thead>
                    <tr style="background:#e2e8f0;">
                      <th style="padding:12px;color:#334155;font-size:11px;font-weight:800;text-align:center;text-transform:uppercase;letter-spacing:.5px;">#</th>
                      <th style="padding:12px 14px;color:#334155;font-size:11px;font-weight:800;text-align:left;text-transform:uppercase;letter-spacing:.5px;">Page URL</th>
                      <th style="padding:12px;color:#334155;font-size:11px;font-weight:800;text-align:center;text-transform:uppercase;letter-spacing:.5px;">Clicks</th>
                      <th style="padding:12px;color:#334155;font-size:11px;font-weight:800;text-align:center;text-transform:uppercase;letter-spacing:.5px;">Impr.</th>
                      <th style="padding:12px;color:#334155;font-size:11px;font-weight:800;text-align:center;text-transform:uppercase;letter-spacing:.5px;">CTR</th>
                    </tr>
                  </thead>
                  <tbody>${tableRows}</tbody>
                </table>
              </div>
            </td>
          </tr>`;

const htmlReport = shell(summaryBlock + tableBlock);

return [{
  json: {
    htmlReport,
    hasData: true,
    totalQualifying: total,
    dateRange: dateRangeText,
    periodText
  }
}];

const nodeHtmlToImage = require('node-html-to-image');
const data = $input.first().json;
const htmlContent = data.htmlReport;

const imageBuffer = await nodeHtmlToImage({
  html: htmlContent,
  type: 'png',
  puppeteerArgs: {
    executablePath: '/usr/bin/chromium-browser',
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  },
  encoding: 'buffer'
});

return [{
  json: {
    ...data,
    imageGenerated: true
  },
  binary: {
    reportImage: {
      data: imageBuffer.toString('base64'),
      mimeType: 'image/png',
      fileName: 'gsc-report.png'
    }
  }
}];
